import test from 'node:test';
import assert from 'node:assert/strict';
import { createCreditNote } from '../src/credits.js';
import { createInvoice, issueInvoice, invoiceTotals, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('createCreditNote creates credit note for issued invoice', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = createCreditNote(issued.value, { amount: 50000, reason: 'Refund', date: '2026-10-08' }, []);
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'CN-2026-0001');
  assert.equal(result.value.invoiceNumber, 'INV-2026-0001');
  assert.equal(result.value.customerId, 'C-002');
  assert.equal(result.value.amount, 50000);
  assert.equal(result.value.reason, 'Refund');
  assert.equal(result.value.date, '2026-10-08');
});

test('createCreditNote creates credit note for partially_paid invoice', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);
  let invoice = issueInvoice(inv.value, []).value;
  invoice = recordPayment(invoice, { amount: 50000, date: '2026-10-08' }).value;

  const result = createCreditNote(invoice, { amount: 30000, reason: 'Partial refund', date: '2026-10-09' }, []);
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'CN-2026-0001');
});

test('createCreditNote creates credit note for paid invoice', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);
  let invoice = issueInvoice(inv.value, []).value;
  invoice = recordPayment(invoice, { amount: 114950, date: '2026-10-08' }).value;

  const result = createCreditNote(invoice, { amount: 20000, reason: 'Goodwill refund', date: '2026-10-09' }, []);
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'CN-2026-0001');
});

test('createCreditNote handles NOT_ISSUED for draft invoice', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);

  const result = createCreditNote(inv.value, { amount: 50000, reason: 'Refund', date: '2026-10-08' }, []);
  assert.equal(result.ok, false);
  assert.equal(result.error, 'NOT_ISSUED');
});

test('createCreditNote handles AMOUNT_INVALID for zero', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = createCreditNote(issued.value, { amount: 0, reason: 'Refund', date: '2026-10-08' }, []);
  assert.equal(result.ok, false);
  assert.equal(result.error, 'AMOUNT_INVALID');
});

test('createCreditNote handles AMOUNT_INVALID for negative', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = createCreditNote(issued.value, { amount: -50000, reason: 'Refund', date: '2026-10-08' }, []);
  assert.equal(result.ok, false);
  assert.equal(result.error, 'AMOUNT_INVALID');
});

test('createCreditNote handles AMOUNT_INVALID for fractional', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = createCreditNote(issued.value, { amount: 50000.5, reason: 'Refund', date: '2026-10-08' }, []);
  assert.equal(result.ok, false);
  assert.equal(result.error, 'AMOUNT_INVALID');
});

test('createCreditNote handles DATE_INVALID', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = createCreditNote(issued.value, { amount: 50000, reason: 'Refund', date: '08-10-2026' }, []);
  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('createCreditNote handles CREDIT_TOO_HIGH', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);
  // total = 114950
  const result = createCreditNote(issued.value, { amount: 114951, reason: 'Refund', date: '2026-10-08' }, []);
  assert.equal(result.ok, false);
  assert.equal(result.error, 'CREDIT_TOO_HIGH');
});

test('createCreditNote can refund exact invoice total', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = createCreditNote(issued.value, { amount: 114950, reason: 'Full refund', date: '2026-10-08' }, []);
  assert.equal(result.ok, true);
  assert.equal(result.value.amount, 114950);
});

test('createCreditNote increments counter for multiple notes in same year', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result1 = createCreditNote(issued.value, { amount: 50000, reason: 'Refund 1', date: '2026-10-08' }, []);
  assert.equal(result1.ok, true);
  assert.equal(result1.value.number, 'CN-2026-0001');

  const result2 = createCreditNote(issued.value, { amount: 30000, reason: 'Refund 2', date: '2026-10-09' }, ['CN-2026-0001']);
  assert.equal(result2.ok, true);
  assert.equal(result2.value.number, 'CN-2026-0002');
});

test('createCreditNote separates invoice and credit note counters', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, ['INV-2026-0001', 'INV-2026-0002', 'INV-2026-0003']);
  assert.equal(issued.ok, true);

  const result = createCreditNote(issued.value, { amount: 50000, reason: 'Refund', date: '2026-10-08' }, ['INV-2026-0001', 'INV-2026-0002', 'INV-2026-0003']);
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'CN-2026-0001');
});

test('createCreditNote resets counter per year', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
